    step2Content = `* Attendance and classroom management
* Warm-up / Review: "Can anyone tell me what you did yesterday?"
* Students answer using past actions
* Teacher transition: "Today we will study '${rawTopic}' to express ourselves accurately."`;

    step3Content = `${chapter} ${lessonNo}: ${rawTopic}
1. Grammar Rules & Sentence Structures:
- Form & Formula:
  + Positive (+): Subject + Verb + Object
  + Negative (-): Subject + Auxiliary Verb + not + Verb + Object
  + Question (?): Auxiliary Verb + Subject + Verb + Object?
- Usage & Time Expressions (Signal Words)
- Common mistakes to avoid

2. Worked Examples & Step-by-Step Analysis:
* Sample task: Transform and complete sentences using "${rawTopic}"
* 4-Step detailed solution:
- Step 1 (Identify Subject & Time Marker): Determine whether the action is past, present, or future
- Step 2 (Apply correct Verb Form): Choose regular or irregular verb form
- Step 3 (Construct the complete sentence): Combine subject, auxiliary, and main verb correctly
- Step 4 (Verify & Conclude): Check spelling, agreement, and punctuation.

3. Group Activity:
* Team 1: Write 3 positive and negative sentences based on daily routine
* Team 2: Create a short dialogue using the target structure`;

    step4Content = `* Quick Board Assessment:
  Transform: "She (play) football yesterday."
* Answer: "She played football yesterday."`;

    step5Content = `* Homework Assignment:
- Complete exercises in textbook page 45
- Write 5 original sentences using "${rawTopic}"`;

    boardSummary = `Subject: ${subject} | Grade: ${grade}
${chapter} ${lessonNo}: ${rawTopic}
-----------------------------------------------------------
1. Structure: (+) S + V + O | (-) S + aux + not + V | (?) Aux + S + V?
2. Signal Words: yesterday, last week, ago...
3. Examples & Practice`;
