   - រាងមូលគែមក្រហម (ហាមឃាត់) | រាងមូលបាតខៀវ (បង្គាប់)
   - រាងត្រីកោណគែមក្រហម (គ្រោះថ្នាក់/ប្រយ័ត្ន)
